def _normalize(table, normalize, margins, margins_name="All"):
    if not isinstance(normalize, (bool, str)):
        axis_subs = {0: "index", 1: "columns"}
        try:
            normalize = axis_subs[normalize]
        except KeyError:
            raise ValueError("Not a valid normalize argument")

    if margins is False:
        normalizers = {
            "all": lambda x: x / x.sum(axis=1).sum(axis=0),
            "columns": lambda x: x / x.sum(),
            "index": lambda x: x.div(x.sum(axis=1), axis=0),
        }
        normalizers[True] = normalizers["all"]
        try:
            f = normalizers[normalize]
        except KeyError:
            raise ValueError("Not a valid normalize argument")
        table = f(table)
        table = table.fillna(0)
    elif margins is True:
        if normalize not in ["index", "columns", "all", True]:
            raise ValueError("Not a valid normalize argument")
        if margins_name not in table.index.get_level_values(-1).values and margins_name not in table.columns.get_level_values(-1).values:
            raise ValueError(f"`margins_name` '{margins_name}' not found in index or columns")
        column_margin = table.xs(margins_name, axis=1, level=-1)
        index_margin = table.xs(margins_name, axis=0, level=-1)
        table = table.drop(margins_name, axis=1, level=-1).drop(margins_name, axis=0, level=-1)
        table = _normalize(table, normalize, False)
        if normalize == "columns":
            column_margin = column_margin / column_margin.sum()
            table = pd.concat([table, column_margin], ignore_index=False, axis=1)
            table = table.fillna(0)
        elif normalize == "index":
            index_margin = index_margin / index_margin.sum()
            table = pd.concat([table, index_margin.to_frame().T], ignore_index=False, axis=0)
            table = table.fillna(0)
        elif normalize == "all" or normalize is True:
            column_margin = column_margin / column_margin.sum()
            index_margin = index_margin / index_margin.sum()
            table = pd.concat([table, column_margin], ignore_index=False, axis=1)
            table = pd.concat([table, index_margin.to_frame().T], ignore_index=False, axis=0)
            table = table.fillna(0)
    else:
        raise ValueError("Not a valid margins argument")
    return table
